const itemsOutput = [];
const inputItem = items[0].json;

// 1. 從上游節點（HTTP Request1）獲取 API 返回的完整食譜數據
// 修正：targetRecipe 就是 inputItem 本身
const targetRecipe = inputItem; 

// 2. 確保 replyToken 存在
const replyToken = targetRecipe.replyToken; 


// 3. 檢查 API 是否返回有效的食譜數據（例如，檢查 title 欄位）
if (targetRecipe && targetRecipe.title) {
    // 4. 格式化文本內容
    const recipeTitle = targetRecipe.title.trim();
    // 修正：LINE Message 不支援 Markdown 的 **，我們使用換行來強調
    let textMessage = `🍲 ${recipeTitle} 完整詳情 🍲\n\n`;
    textMessage += "--- 🍳 材料清單 ---\n";
    
    // 使用原始材料字串
    textMessage += `${targetRecipe.ingredients_raw || "未提供材料清單"}\n\n`;
    
    textMessage += "--- 📜 烹飪步驟 ---\n";
    
    // 修正：使用正確的陣列處理邏輯 (steps_raw 是 [ { description: "..." }, ... ] )
    if (targetRecipe.steps_raw && Array.isArray(targetRecipe.steps_raw) && targetRecipe.steps_raw.length > 0) {
        textMessage += targetRecipe.steps_raw.map((step, index) => 
            // 使用 .trim() 移除描述前後的空格
            `步驟 ${index + 1}: ${step.description.trim()}` 
        ).join('\n');
    } else {
        textMessage += "未提供詳細步驟。\n";
    }

    // 5. 生成 LINE Text Message 結構
    // 注意：LINE Message 文本長度限制為 2000 個字符，如果超過可能也會導致 Bad Request
    const lineMessages = [
        {
            "type": "text",
            "text": textMessage
        }
    ];

    // 6. 返回給下游節點的 Item (包含 messages 和 replyToken)
    itemsOutput.push({ 
        json: { 
            "messages": lineMessages,
            "replyToken": replyToken 
        } 
    });
} else {
    // 找不到食譜時的錯誤回覆
    itemsOutput.push({ 
        json: {
            "messages": [{ "type": "text", "text": `抱歉，找不到您查詢的食譜詳情。` }],
            "replyToken": replyToken
        } 
    });
}

return itemsOutput;
